using Jellyfin.Plugin.Wun;
using Xunit;
public sealed class SearchRulesTests
{
 [Fact]public void MultipleTypePlansUseUnionWithoutDuplicateQueries(){var mixed=SearchRules.SearchPlan("Movie,Anime");Assert.Equal(new[]{("Movie",false),("Series",true)},mixed);Assert.Equal(new[]{("Movie",true),("Series",false)},SearchRules.SearchPlan("Series,Anime"));Assert.Equal(new[]{("Movie",false),("Series",false)},SearchRules.SearchPlan("All,Anime"));Assert.Single(SearchRules.SearchPlan("Movie,Movie"));Assert.False(SearchRules.ValidKinds("Movie,Unknown"));}
 [Fact]public void AnimeUsesMetadataRatherThanEveryAnimation(){Assert.True(SearchRules.IsAnime(["Animation"],["anime"],[]));Assert.True(SearchRules.IsAnime(["Animação"],[],["Japan"]));Assert.False(SearchRules.IsAnime(["Animation"],[],["United States of America"]));Assert.False(SearchRules.IsAnime(["Drama"],[],["Japan"]));}
 [Fact]public void CombinedSearchKeepsTypesDistinctAndBalanced(){var movies=Enumerable.Range(1,12).Select(i=>new SearchCard("Movie",i.ToString(),"Movie",2020)).ToArray();var series=Enumerable.Range(1,12).Select(i=>new SearchCard("Series",i.ToString(),"Series",2020)).ToArray();var result=SearchRules.Combine(movies,series);Assert.Equal(12,result.Length);Assert.Equal(6,result.Count(x=>x.Kind=="Movie"));Assert.Equal(6,result.Count(x=>x.Kind=="Series"));Assert.Equal("Movie",result[0].Kind);Assert.Equal("Series",result[1].Kind);Assert.Equal(result[0].TmdbId,result[1].TmdbId);Assert.Equal(12,SearchRules.Combine(movies,[]).Length);}
 [Theory][InlineData("tt0083658","Imdb","tt0083658")][InlineData("imdb:tt0083658","Imdb","tt0083658")][InlineData("https://www.imdb.com/title/tt0083658/?ref_=test","Imdb","tt0083658")][InlineData("TT0083658","Imdb","tt0083658")][InlineData("tmdb:78","Tmdb","78")][InlineData("78","Tmdb","78")]
 public void IdentifiersAreCanonical(string query,string provider,string id){var actual=SearchRules.Identifier(query);Assert.Equal(provider,actual.Provider);Assert.Equal(id,actual.Id);}
 [Theory][InlineData("https://imdb.com.evil.test/title/tt0083658/")][InlineData("javascript:tt0083658")][InlineData("imdb:tt1")][InlineData("Film name")]
 public void UntrustedUrlsAndMalformedIdsAreNotInterpretedAsIdentifiers(string value)=>Assert.Null(SearchRules.Identifier(value).Provider);
 [Fact]public void FiltersCombineAndNormalizeAccents(){var card=new SearchCard("Movie","78","Example",1982,null,"tt0083658",["Ficção científica","Drama"],8.1f,new(true));Assert.True(SearchRules.Matches(card,new(1980,1990,"ficcao",8,"yes")));Assert.False(SearchRules.Matches(card,new(1990,null)));Assert.False(SearchRules.Matches(card,new(MinRating:9)));Assert.False(SearchRules.Matches(card,new(Genres:"romance")));Assert.False(SearchRules.Matches(card,new(Obtained:"no")));}
 [Fact]public void UnknownYearAndRatingDoNotPassNumericFilters(){var card=new SearchCard("Series","1","Example",null);Assert.False(SearchRules.Matches(card,new(YearFrom:2000)));Assert.False(SearchRules.Matches(card,new(MinRating:1)));Assert.False(SearchRules.Valid(new(MinRating:double.NaN)));}
}
